      try {
        if (typeof item.handle === 'function') item.handle();
        else item.handle?.stop?.() || item.handle?.unsubscribe?.() || item.handle?.off?.();
        if (typeof globalThis.eventOff === 'function') globalThis.eventOff(item.eventName, item.handler);
