    }
    if (globalThis[CONFIG.runtimeKey]?.dispose === dispose) delete globalThis[CONFIG.runtimeKey];
  };
  const boot = () => {
    apply();
    const events = [
      globalThis.tavern_events?.CHAT_CHANGED,
      globalThis.tavern_events?.MESSAGE_SENT,
      globalThis.tavern_events?.MESSAGE_SWIPED,
