    }
    if (action === "api:presets") {
      const st = window.SillyTavern || {};
      try {
        const presets = await st.getPresetManager?.()?.getPresets?.();
        if (Array.isArray(presets)) return presets.map((item) => item.name || item).filter(Boolean);
      } catch {
        // 无可用预设时返回空数组。
